/** 已保存的七个模型选择保持原 ID；图像引用使原组合模型选择其编辑操作。 */
export const RUNNINGHUB_LEGACY_MODELS = {
  nanobanana: ['rhart-image-v1-official/text-to-image', 'rhart-image-v1-official/edit'],
  'nanobanana-pro': ['rhart-image-n-pro-official/text-to-image', 'rhart-image-n-pro-official/edit'],
  'nanobanana-2': ['rhart-image-n-g31-flash-official/text-to-image', 'rhart-image-n-g31-flash-official/image-to-image'],
  'gpt-image-2': ['rhart-image-g-2-official/text-to-image', 'rhart-image-g-2-official/image-to-image'],
  'youchuan-v81': ['youchuan/text-to-image-v81'],
  'youchuan-v7': ['youchuan/text-to-image-v7'],
  'youchuan-v6': ['youchuan/text-to-image-v6'],
} as const;

const LEGACY_VARIANTS: Record<string, keyof typeof RUNNINGHUB_LEGACY_MODELS> = {
  'rhart-image-v1': 'nanobanana', 'rhart-image-v1-official': 'nanobanana',
  'rhart-image-n-pro': 'nanobanana-pro', 'rhart-image-n-pro-official': 'nanobanana-pro',
  'rhart-image-n-g31-flash': 'nanobanana-2', 'rhart-image-n-g31-flash-official': 'nanobanana-2',
  'rhart-image-g-2': 'gpt-image-2', 'rhart-image-g-2-official': 'gpt-image-2',
};
export const normalizeRunningHubModelId = (model: string): string => model.replace(/^(?:runninghub-model|runninghub)\//, '');
const BY_ID = new Map(RUNNINGHUB_MODEL_MANIFEST.map((model) => [model.id, model]));
export function getRunningHubModel(model: string | undefined, hasImageReferences = false): RunningHubModelDefinition | undefined {
  if (!model) return undefined;
  const id = normalizeRunningHubModelId(model);
  const legacy = RUNNINGHUB_LEGACY_MODELS[(LEGACY_VARIANTS[id] ?? id) as keyof typeof RUNNINGHUB_LEGACY_MODELS];
  const endpoint = legacy ? legacy[hasImageReferences && legacy.length > 1 ? 1 : 0] : id;
  return endpoint ? BY_ID.get(endpoint) : undefined;
}
export const isLegacyRunningHubModel = (model: string): boolean => {
  const id = normalizeRunningHubModelId(model);
  return Object.hasOwn(RUNNINGHUB_LEGACY_MODELS, id) || Object.hasOwn(LEGACY_VARIANTS, id);
};

/** UI、对话与实际请求共享的值转换；不把空值转为 0，不吞掉 false。 */
export function parseRunningHubModelParameter(field: RunningHubModelParameter, raw?: string): RunningHubModelValue | undefined {
  const schema = field.schema;
  let value: RunningHubModelValue | undefined = field.defaultValue;
  if (raw !== undefined) {
    if (!raw.trim()) value = undefined;
    else if (schema.type === 'array') {
      let parsed: unknown;
      try { parsed = JSON.parse(raw); } catch { throw new Error(`${field.label} 需要 JSON 字符串数组`); }
      if (!Array.isArray(parsed) || parsed.some((item) => typeof item !== 'string')) throw new Error(`${field.label} 需要 JSON 字符串数组`);
      value = parsed;
    } else if (schema.type === 'boolean') {
      if (!['true', 'false'].includes(raw)) throw new Error(`${field.label} 必须是 true 或 false`);
      value = raw === 'true';
    } else if (schema.type === 'number' || schema.type === 'integer') value = Number(raw);
    else value = raw;
  }
  if (value === undefined || value === '' || (Array.isArray(value) && !value.length)) {
    if (field.required) throw new Error(`请填写${field.label}`);
    return undefined;
  }
  if (schema.type === 'number' || schema.type === 'integer') {
    if (typeof value !== 'number' || !Number.isFinite(value) || (schema.type === 'integer' && !Number.isSafeInteger(value))) throw new Error(`${field.label} 需要有效${schema.type === 'integer' ? '整数' : '数字'}`);
    if ((schema.minimum !== undefined && value < schema.minimum) || (schema.maximum !== undefined && value > schema.maximum)) throw new Error(`${field.label} 超出允许范围 ${schema.minimum ?? '不限'}–${schema.maximum ?? '不限'}`);
    if (schema.multipleOf && Math.abs(value / schema.multipleOf - Math.round(value / schema.multipleOf)) > 1e-7) throw new Error(`${field.label} 必须以 ${schema.multipleOf} 为步长`);
  } else if (schema.type === 'string') {
    if (typeof value !== 'string' || value.length < (schema.minLength ?? 0) || value.length > Math.min(schema.maxLength ?? 100_000, 100_000)) throw new Error(`${field.label} 长度不符合要求`);
  } else if (schema.type === 'boolean' && typeof value !== 'boolean') throw new Error(`${field.label} 需要布尔值`);
  if (schema.enum && !schema.enum.includes(value as string | number | boolean)) throw new Error(`${field.label} 不在允许的选项中`);
  if (schema.type === 'array') {
    if (!Array.isArray(value) || value.length < (schema.minItems ?? 0) || value.length > Math.min(schema.maxItems ?? 64, 64) || value.some((entry) => entry.length > 100_000 || (schema.items?.enum && !schema.items.enum.includes(entry)))) throw new Error(`${field.label} 数量或选项不符合要求`);
  }
  return value;
}
